252	\section{The Pauli basis test}
253	% Paper label sec:qld-game kept for cross-reference fidelity.
254	\label{sec:qld-game}
255	
256	The Pauli basis test is the quantum low individual degree test of Natarajan and Vidick, in the slightly modified form introduced by Natarajan and Wright~\cite{Natarajan2018NEEXP}. Informally, the test certifies that the players share the state $\ket{\mathrm{EPR}_q}^{\ot M}$, where $M = 2^m$. On a question of type $(\mathsf{Pauli}, W)$ with $W \in \{X,Z\}$, a player is expected to measure the generalized Pauli basis POVM $\{\tau^W_h\}_{h \in \F_q^M}$ of Chapter~\ref{chap:qpbt-algebra} and report the outcome $h$. Most subtests probe limited information about $h$: given a point $u_W \in \F_q^m$, a player is expected to report the evaluation $g_h(u_W)$ of the low-degree encoding $g_h$ of $h$, and for a fixed basis $W$ these probes are checked against each other by the classical low individual degree game of Section~\ref{sec:ld-verifier}. Consistency \emph{between} the two bases is checked through two-outcome probes: given additionally $r_W \in \F_q$, a player reports $\tr(g_h(u_W)\, r_W) \in \F_2$. The two binary measurements obtained in this way for $W = X$ and $W = Z$ either commute or anticommute, according to the value $\gamma \in \F_2$ of Equation~\eqref{eq:gamma-value} below. When $\gamma = 0$ the verifier checks commutation directly by asking for both bits simultaneously; when $\gamma = 1$ the verifier checks anticommutation by playing the Magic Square game, using Theorem~\ref{thm:ms-from-ac}.
257	
258	\begin{definition}[Admissible parameters]\label{def:admissible}
259		\uses{def:admissible-size}
260		% The source introduces q, m, d in \N with \N the positive integers
261		% (references/qpbt-paper/04_preliminaries.tex:6 and
262		% references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:903-905),
263		% so d >= 1 is implicit in its notion of admissibility (lines 958-961 there);
264		% we state it explicitly. It is load-bearing: at d = 0 the soundness function
265		% delta_qld of thm:pauli vanishes identically while every strategy satisfies
266		% the success hypothesis at eps = 1, and the low-degree check of
267		% def:pauli-win-predicate invokes the classical game at ldparams = (q,m,d,1),
268		% whose domain (Definition def:ld-game) requires d >= 1. The hypothesis
269		% propagates to lem:pauli-completeness, thm:pauli, and cor:pauli-binary
270		% through their quantification over admissible tuples.
271		The tuple $\mathsf{qldparams} = (q,m,d)$ is \emph{admissible} if $d \ge 1$, $q$ is an admissible field size (Definition~\ref{def:admissible-size}), and $m$ divides $q$. Since an admissible field size satisfies $q \ge 2$, the divisibility forces $m \ge 1$, so an admissible tuple has all entries positive.
272	\end{definition}
273	
274	\begin{definition}[Question distribution of the Pauli basis test]\label{def:pauli-question-distribution}
275		\uses{def:admissible, def:ld-question-distribution, def:ms-game, def:cl-func, def:cl-dist, def:graph-distribution}
276		% Admissibility of the full tuple is required here, not only the divisibility m | q:
277		% the source parametrizes the Pauli basis test by the tuple qldparams introduced
278		% together with Definition def:admissible (references/qpbt-paper/
279		% 08_classical_and_quantum_low_degree_tests.tex:958-1075), and both the fixed binary
280		% identification of F_q used by the map chi and the trace tr in eq:gamma-value
281		% require q to be a power of 2.
282		The game $\mathcal G^{\mathrm{pauli}}$ (also $\mathcal G^{\mathrm{pauli}}_{\mathsf{qldparams}}$) is parametrized by an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}): admissibility makes $q$ a power of $2$, so that the field $\F_q$, its fixed identification with binary strings (Chapter~\ref{chap:qpbt-algebra}), and the trace $\tr\colon \F_q \to \F_2$ used by the win predicate below are defined, and it provides the divisibility $m \mid q$ required by the index map $\chi$ of Definition~\ref{def:ld-question-distribution}. The question type set is
283		\begin{equation}
284			\label{eq:pauli-type}
285			\mathcal T^{\mathrm{pauli}} = \bigl( \{\mathsf{Point}, \mathsf{ALine}, \mathsf{DLine}, \mathsf{Pauli}, \mathsf{Pair}\} \times \{X,Z\} \bigr) \cup \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}\}\;,
286		\end{equation}
287		where $\mathcal T^{\mathrm{ms}}$ is the type set of the Magic Square game (Definition~\ref{def:ms-game}).
288	
289		The ambient space is $V^{\mathrm{pauli}} = (\F_q^m)^2 \times \F_q \times \F_q^m \times (\F_q)^2$, decomposed into the register subspaces $V_X, V_Z$ (each $m$-dimensional over $\F_q$), $V_I$ ($1$-dimensional), $V_V$ ($m$-dimensional), and $V_{R_X}, V_{R_Z}$ ($1$-dimensional each); elements of $V^{\mathrm{pauli}}$ are written $(u_X, u_Z, s, v, r_X, r_Z)$. For each type $t \in \mathcal T^{\mathrm{pauli}}$ define a CL function $L_t\colon V^{\mathrm{pauli}} \to V^{\mathrm{pauli}}$ as follows, where $L_{\mathsf{Point}}, L_{\mathsf{ALine}}, L_{\mathsf{DLine}}$ are the CL functions of Definition~\ref{def:ld-question-distribution}:
290		\begin{enumerate}
291			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Point},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{Point}}(u_W,s,v)$, a $1$-level CL function, where the range $V_W \oplus V_I \oplus V_V$ of $L_{\mathsf{Point}}$ is embedded in $V^{\mathrm{pauli}}$ in the natural way (the same convention applies in items~2 and~3);
292			\item for $W \in \{X,Z\}$, $L_{(\mathsf{ALine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{ALine}}(u_W,s,v)$, a $2$-level CL function;
293			\item for $W \in \{X,Z\}$, $L_{(\mathsf{DLine},W)}(u_X,u_Z,s,v,r_X,r_Z) = L_{\mathsf{DLine}}(u_W,s,v)$, a $3$-level CL function;
294			\item for $t \in \mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$, $L_t(u_X,u_Z,s,v,r_X,r_Z) = (u_X,u_Z,0,0,r_X,r_Z)$, the $1$-level CL function projecting onto $V_X \oplus V_Z \oplus V_{R_X} \oplus V_{R_Z}$;
295			\item for $W \in \{X,Z\}$, $L_{(\mathsf{Pauli},W)} = 0$, the identically zero ($0$-level) CL function.
296		\end{enumerate}
297		The maps $L_{(\mathsf{Point},W)}$, $L_{(\mathsf{ALine},W)}$, $L_{(\mathsf{DLine},W)}$ act as the zero function on $V_{\overline W} \oplus V_{R_X} \oplus V_{R_Z}$, where $\overline W$ denotes the basis other than $W$.
298	
299		The \emph{type graph} $G^{\mathrm{pauli}}$ has vertex set $\mathcal T^{\mathrm{pauli}}$ and the following edges: all $18$ edges of the Magic Square type graph $G^{\mathrm{ms}}$ (Definition~\ref{def:ms-game}); the edges
300		\begin{align*}
301			&(\mathsf{ALine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{DLine},X) \,\text{---}\, (\mathsf{Point},X)\;, &&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pauli},X)\;,\\
302			&(\mathsf{ALine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{DLine},Z) \,\text{---}\, (\mathsf{Point},Z)\;, &&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pauli},Z)\;,\\
303			&(\mathsf{Point},X) \,\text{---}\, \mathsf{Variable}_1\;, &&(\mathsf{Point},Z) \,\text{---}\, \mathsf{Variable}_5\;, &&\\
304			&(\mathsf{Point},X) \,\text{---}\, (\mathsf{Pair},X)\;, &&(\mathsf{Pair},X) \,\text{---}\, \mathsf{Pair}\;, &&\\
305			&(\mathsf{Point},Z) \,\text{---}\, (\mathsf{Pair},Z)\;, &&(\mathsf{Pair},Z) \,\text{---}\, \mathsf{Pair}\;; &&
306		\end{align*}
307		and, in addition, a self-loop at every vertex.
308	
309		% The type pair is drawn from the graph distribution of Definition
310		% def:graph-distribution, matching the source's formal definition
311		% (references/qpbt-paper/07_types.tex:84-93 together with
312		% references/qpbt-paper/08_classical_and_quantum_low_degree_tests.tex:1115-1120).
313		% Sampling an undirected edge uniformly and then ordering its
314		% endpoints uniformly would be a different distribution here: it gives each self-loop
315		% twice the relative mass of an oriented non-loop pair, and G^pauli has a self-loop
316		% at every vertex.
317		The question distribution of $\mathcal G^{\mathrm{pauli}}$ is the typed CL distribution on $\mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}} \times \mathcal T^{\mathrm{pauli}} \times V^{\mathrm{pauli}}$ obtained by sampling the type pair $(t_{\mathrm A}, t_{\mathrm B})$ from the graph distribution $\mu_{G^{\mathrm{pauli}}}$ of Definition~\ref{def:graph-distribution}, that is, uniformly at random among all ordered pairs of types whose underlying unordered pair $\{t_{\mathrm A}, t_{\mathrm B}\}$ is an edge of $G^{\mathrm{pauli}}$, self-loops included; sampling $z \in V^{\mathrm{pauli}}$ uniformly at random; and setting $x_w = L_{t_w}(z)$ for $w \in \{\mathrm A,\mathrm B\}$. Explicitly, if $z = (u_X,u_Z,s,v,r_X,r_Z)$, then a player whose type is $(\mathsf{Point},W)$ receives $u_W$; a player whose type is $(\mathsf{ALine},W)$ receives $(u_0, s)$ with $u_0 = L^{\mathrm{Ln}}_{e_i}(u_W)$ and $i = \chi(s)$; a player whose type is $(\mathsf{DLine},W)$ receives $(u_0, s, v')$ with $i = \chi(s)$, $v' = \pi_{i-1}(v)$, and $u_0 = L^{\mathrm{Ln}}_{v'}(u_W)$; a player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ receives $(u_X, u_Z, r_X, r_Z)$; and a player whose type is $(\mathsf{Pauli},W)$ receives $0$.
318	\end{definition}
319	
320	\begin{definition}[Win predicate of the Pauli basis test]\label{def:pauli-win-predicate}
321		\uses{def:pauli-question-distribution, def:ld-win-predicate, def:ms-game, def:indicator-vector, def:admissible}
322		Fix an admissible tuple $\mathsf{qldparams} = (q,m,d)$ (Definition~\ref{def:admissible}) and let $M = 2^m$. Answers in the game $\mathcal G^{\mathrm{pauli}}_{\mathsf{qldparams}}$ take the following forms, depending on the question type; answers not of the prescribed form are rejected.
323		% The paper's format table writes the line contents loosely as (u_W, s) and (u_W, s, v);
324		% by the sampling procedure the actual contents are the canonical pairs (u_0, s) and
325		% triples (u_0, s, v') with v' = pi_{i-1}(v). We state the canonical form.
326		\begin{itemize}
327			\item $(\mathsf{Point},W)$: content $y \in \F_q^m$; answer an element of $\F_q$.
328			\item $(\mathsf{ALine},W)$: content $(u_0, s) \in \F_q^m \times \F_q$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $d$.
329			\item $(\mathsf{DLine},W)$: content $(u_0, s, v') \in \F_q^m \times \F_q \times \F_q^m$; answer a univariate polynomial $f\colon \F_q \to \F_q$ of degree at most $md$.
330			\item $\mathsf{Pair}$: content $\omega = (u_X, u_Z, r_X, r_Z) \in (\F_q^m)^2 \times \F_q^2$; answer $(\beta_X, \beta_Z) \in \F_2^2$.
331			\item $(\mathsf{Pair},W)$: content $\omega$ as above; answer an element of $\F_2$.
332			\item $\mathsf{Constraint}_i$: content $\omega$ as above; answer $(\alpha_{v_1}, \alpha_{v_2}, \alpha_{v_3}) \in \F_2^3$, indexed by the variable indices $(v_1,v_2,v_3)$ of $\mathsf{Constraint}_i$.
333			\item $\mathsf{Variable}_j$: content $\omega$ as above; answer an element of $\F_2$.
334			\item $(\mathsf{Pauli},W)$: content $0$; answer an element of $\F_q^M$.
335		\end{itemize}
336		The win predicate $D^{\mathrm{pauli}} = D^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the function of the tuple $(t_{\mathrm A}, x_{\mathrm A}, t_{\mathrm B}, x_{\mathrm B}, a_{\mathrm A}, a_{\mathrm B})$ determined by the following clauses, evaluated for $w \in \{\mathrm A, \mathrm B\}$ and $W \in \{X,Z\}$; in all cases where no action is indicated, the predicate accepts. In the last four clauses, the content of the player whose type lies in $\mathcal T^{\mathrm{ms}} \cup \{\mathsf{Pair}, (\mathsf{Pair},X), (\mathsf{Pair},Z)\}$ is a tuple $(u_X, u_Z, r_X, r_Z)$, from which the predicate first computes
337		\begin{equation}
338			\label{eq:gamma-value}
339			\gamma = \tr\bigl( (\mathrm{ind}_m(u_X) \cdot r_X) \cdot (\mathrm{ind}_m(u_Z) \cdot r_Z) \bigr) \in \F_2\;,
340		\end{equation}
341		where $\mathrm{ind}_m(\cdot) \in \F_q^M$ is the indicator vector of the low-degree encoding (Chapter~\ref{chap:qpbt-algebra}), the inner dot denotes the dot product on $\F_q^M$, and $\tr\colon \F_q \to \F_2$ is the finite-field trace.
342		\begin{enumerate}
343			\item (\textbf{Consistency check}) If $t_{\mathrm A} = t_{\mathrm B}$, accept if and only if $a_{\mathrm A} = a_{\mathrm B}$.
344			\item (\textbf{Low-degree check}) Let $\mathsf{ldparams} = (q,m,d,1)$; admissibility of $\mathsf{qldparams}$ gives $d \ge 1$ and $m \mid q$, so this is a parameter tuple as in Definition~\ref{def:ld-game}.
345			\begin{enumerate}
346				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{ALine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{ALine}, x_{\overline w}, a_w, a_{\overline w})$.
347				\item If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{DLine},W)$, accept if $D^{\mathrm{ld}}_{\mathsf{ldparams}}$ accepts $(\mathsf{Point}, x_w, \mathsf{DLine}, x_{\overline w}, a_w, a_{\overline w})$.
348			\end{enumerate}
349			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pauli},W)$, accept if $g_{a_{\overline w}}(x_w) = a_w$, where $g_{a_{\overline w}}$ is the low-degree encoding of $a_{\overline w} \in \F_q^M$ (Chapter~\ref{chap:qpbt-algebra}).
350			\item (\textbf{Commutation check}) If $t_w = (\mathsf{Pair},W)$ and $t_{\overline w} = \mathsf{Pair}$, accept if $a_w = \beta_W$ or $\gamma \neq 0$.
351			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = (\mathsf{Pair},W)$, accept if $\tr(a_w r_W) = a_{\overline w}$ or $\gamma \neq 0$.
352			\item (\textbf{Magic Square check}) If $t_w = \mathsf{Constraint}_i$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $a_w$ satisfies the equation of $\mathsf{Constraint}_i$ and $\alpha_j = a_{\overline w}$.
353			\item (\textbf{Consistency check}) If $t_w = (\mathsf{Point},W)$ and $t_{\overline w} = \mathsf{Variable}_j$, accept if $\gamma = 0$, or if $j = 1$, $W = X$, and $\tr(a_w r_X) = a_{\overline w}$, or if $j = 5$, $W = Z$, and $\tr(a_w r_Z) = a_{\overline w}$.
354		\end{enumerate}
355		The game $\mathcal G^{\mathrm{pauli}}_{\mathsf{qldparams}}$ is the typed game with type set $\mathcal T^{\mathrm{pauli}}$, the question distribution of Definition~\ref{def:pauli-question-distribution}, and win predicate $D^{\mathrm{pauli}}_{\mathsf{qldparams}}$.
356	\end{definition}
357	
358	Note the one-sided gating on $\gamma$: the commutation check and the $\mathsf{Pair}$ consistency check accept automatically when $\gamma \neq 0$, while the Magic Square check and the $\mathsf{Variable}$ consistency check accept automatically when $\gamma = 0$.
359	
360	\begin{lemma}[Completeness of the Pauli basis test]\label{lem:pauli-completeness}

430		Stated in the source without proof; it is Fact 4.32 of \cite{Natarajan2018NEEXP}. Write the value difference as an average over $(x,y) \sim \mu$ of sums of terms of the form $\bra{\psi} (A^x_a - (A')^x_a) \ot B^y_b \ket{\psi}$ and $\bra{\psi} (A')^x_a \ot (B^y_b - (B')^y_b) \ket{\psi}$, replacing one player's measurements at a time. The Cauchy--Schwarz inequality bounds each group by the square root of the corresponding averaged squared state-dependent distance, and projectivity of one of the two strategies keeps the accompanying operator sums bounded, giving the total bound $O(\delta^{1/2})$.
431	\end{proof}
